import{_ as p,W as d,s as o,u as l,ah as r,I as t,w as s,Z as a,A as i}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const v=JSON.parse('{"title":"谨慎使用 Linux find 命令 | LCTT x X-CMD","titleTemplate":false,"description":"谨慎使用 Linux find 命令 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"谨慎使用 Linux find 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谨慎使用 Linux find 命令 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171016 Using the Linux find command with caution","title":"谨慎使用 Linux find 命令","tag":"201802"},"relativePath":"201802/20171016 Using the Linux find command with caution.md","filePath":"[post].md"}'),c={name:"201802/20171016 Using the Linux find command with caution.md"};function u(m,n,h,g,b,k){const e=d("Link");return l(),o("div",null,[n[18]||(n[18]=r(`<h1 id="谨慎使用-linux-find-命令" tabindex="-1">谨慎使用 Linux find 命令 <a class="header-anchor" href="#谨慎使用-linux-find-命令" aria-label="Permalink to 谨慎使用 Linux find 命令">​</a></h1><blockquote><p>当使用 Linux 下的 find 命令时，请使用 -ok 选项来避免文件被意外删除，这个选项会在移除任何文件之前都会请求你的许可。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/10/caution-sign-100738884-large.jpg" alt=""></p><p>最近有朋友提醒我有一个有用的选项来更加谨慎地运行 <code>find</code> 命令，它就是 <code>-ok</code>。除了一个重要的区别之外，它的工作方式与 <code>-exec</code> 相似，它使 <code>find</code> 命令在执行指定的操作之前请求权限。</p><p>这有一个例子。如果你使用 <code>find</code> 命令查找文件并删除它们，你可能使用的是下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -exec rm {} \\;</span></span></code></pre></div><p>在当前目录及其子目录中中任何名为 “runme” 的文件都将被立即删除 —— 当然，你要有权限删除它们。改用 <code>-ok</code> 选项，你会看到类似这样的东西，但 <code>find</code> 命令将在删除文件之前会请求权限。回答 <code>y</code> 代表 “yes” 将允许 <code>find</code> 命令继续并逐个删除文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -ok rm {} \\;</span></span>
<span class="line"><span>&lt; rm ... ./bin/runme &gt; ?</span></span></code></pre></div><h3 id="execdir-命令也是一个选择" tabindex="-1">-execdir 命令也是一个选择 <a class="header-anchor" href="#execdir-命令也是一个选择" aria-label="Permalink to -execdir 命令也是一个选择">​</a></h3><p>另一个可以用来修改 <code>find</code> 命令行为，并可能使其更可控的选项是 <code>-execdir</code> 。<code>-exec</code> 会运行指定的任何命令，而 <code>-execdir 则从文件所在的目录运行指定的命令，而不是在运行 </code>find\` 命令的目录运行指定的命令。这是两个它的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/shs</span></span>
<span class="line"><span>$ find . -name runme -execdir pwd \\;</span></span>
<span class="line"><span>/home/shs/bin</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -execdir ls \\;</span></span>
<span class="line"><span>ls rm runme</span></span></code></pre></div><p>到现在为止还挺好。但要记住的是，<code>-execdir</code> 也会在匹配文件的目录中执行该命令。如果运行下面的命令，并且目录包含一个名为 “ls” 的文件，那么即使该文件_没有_执行权限，它也将运行该文件。使用 <code>-exec</code> 或 <code>-execdir</code> 类似于通过 <code>source</code> 来运行命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -execdir ls \\;</span></span>
<span class="line"><span>Running the /home/shs/bin/ls file</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -execdir rm {} \\;</span></span>
<span class="line"><span>This is an imposter rm command</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls -l bin</span></span>
<span class="line"><span>total 12</span></span>
<span class="line"><span>-r-x------ 1 shs shs 25 Oct 13 18:12 ls</span></span>
<span class="line"><span>-rwxr-x--- 1 shs shs 36 Oct 13 18:29 rm</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 28 Oct 13 18:55 runme</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat bin/ls</span></span>
<span class="line"><span>echo Running the $0 file</span></span>
<span class="line"><span>$ cat bin/rm</span></span>
<span class="line"><span>echo This is an imposter rm command</span></span></code></pre></div><h3 id="okdir-选项也会请求权限" tabindex="-1">-okdir 选项也会请求权限 <a class="header-anchor" href="#okdir-选项也会请求权限" aria-label="Permalink to -okdir 选项也会请求权限">​</a></h3><p>要更谨慎，可以使用 <code>-okdir</code> 选项。类似 <code>-ok</code>，该选项将请求权限来运行该命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -okdir rm {} \\;</span></span>
<span class="line"><span>&lt; rm ... ./bin/runme &gt; ?</span></span></code></pre></div><p>你也可以小心地指定你想用的命令的完整路径，以避免像上面那样的冒牌命令出现的任何问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ find . -name runme -execdir /bin/rm {} \\;</span></span></code></pre></div><p><code>find</code> 命令除了默认打印之外还有很多选项，有些可以使你的文件搜索更精确，但谨慎一点总是好的。</p>`,23)),t("p",null,[n[2]||(n[2]=s("在 ")),a(e,{href:"https://www.facebook.com/NetworkWorld/"},{default:i(()=>n[0]||(n[0]=[s("Facebook")])),_:1}),n[3]||(n[3]=s(" 和 ")),a(e,{href:"https://www.linkedin.com/company/network-world"},{default:i(()=>n[1]||(n[1]=[s("LinkedIn")])),_:1}),n[4]||(n[4]=s(" 上加入 Network World 社区来进行评论。"))]),n[19]||(n[19]=t("hr",null,null,-1)),t("p",null,[n[6]||(n[6]=s("via: ")),a(e,{href:"https://www.networkworld.com/article/3233305/linux/using-the-linux-find-command-with-caution.html"},{default:i(()=>n[5]||(n[5]=[s("https://www.networkworld.com/article/3233305/linux/using-the-linux-find-command-with-caution.html")])),_:1})]),t("p",null,[n[10]||(n[10]=s("作者：")),a(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>n[7]||(n[7]=[s("Sandra Henry-Stocker")])),_:1}),n[11]||(n[11]=s(" 译者：")),a(e,{href:"https://github.com/geekpi"},{default:i(()=>n[8]||(n[8]=[s("geekpi")])),_:1}),n[12]||(n[12]=s(" 校对：")),a(e,{href:"https://github.com/locez"},{default:i(()=>n[9]||(n[9]=[s("Locez")])),_:1})]),t("p",null,[n[15]||(n[15]=s("本文由 ")),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>n[13]||(n[13]=[s("LCTT")])),_:1}),n[16]||(n[16]=s(" 原创编译，")),a(e,{href:"https://linux.cn/"},{default:i(()=>n[14]||(n[14]=[s("Linux中国")])),_:1}),n[17]||(n[17]=s(" 荣誉推出"))])])}const w=p(c,[["render",u]]);export{v as __pageData,w as default};
